#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

struct TrieNode {
    int next[36];
    int count;
    TrieNode() {
        fill(next, next + 36, -1);
        count = 0;
    }
};

vector<TrieNode> trie;

int charToIndex(char c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    return c - '0' + 26;
}

void insert(const string& s) {
    int u = 0;
    for (char c : s) {
        int idx = charToIndex(c);
        if (trie[u].next[idx] == -1) {
            trie[u].next[idx] = trie.size();
            trie.emplace_back();
        }
        u = trie[u].next[idx];
    }
    trie[u].count++;
}

int query(const string& s) {
    int u = 0;
    for (char c : s) {
        int idx = charToIndex(c);
        if (trie[u].next[idx] == -1) return 0;
        u = trie[u].next[idx];
    }
    return trie[u].count;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> passwords(n);
    trie.emplace_back(); // raiz

    for (int i = 0; i < n; ++i) {
        cin >> passwords[i];
        insert(passwords[i]);
    }

    long long total_pairs = 0;

    for (int i = 0; i < n; ++i) {
        const string& s = passwords[i];
        int len = s.length();
        vector<string> substrings;
        substrings.reserve(len * (len + 1) / 2);

        for (int j = 0; j < len; ++j) {
            string sub = "";
            for (int k = j; k < len; ++k) {
                sub += s[k];
                substrings.push_back(sub);
            }
        }

        sort(substrings.begin(), substrings.end());
        substrings.erase(unique(substrings.begin(), substrings.end()), substrings.end());

        long long accessible = 0;
        for (const string& sub : substrings) {
            accessible += query(sub);
        }

        // Subtrai o próprio usuário, pois s é uma substring de s
        accessible -= 1;
        total_pairs += accessible;
    }

    cout << total_pairs << "\n";

    return 0;
}
